mapper.update:
UPDATE pcd_im_conversation
SET unread_count = unread_count + 1, update_time = NOW()
WHERE conversation_id = #{conversationId}

UPDATE pcd_im_conversation
SET unread_count = 0, update_time = NOW()
WHERE conversation_id = #{conversationId}

UPDATE pcd_im_conversation
SET is_top = #{isTop}, update_time = NOW()
WHERE conversation_id = #{conversationId}

UPDATE pcd_im_conversation
SET is_muted = #{isMuted}, update_time = NOW()
WHERE conversation_id = #{conversationId}

UPDATE pcd_im_conversation
SET status = 1, update_time = NOW()
WHERE conversation_id = #{conversationId}

mapper.select:
SELECT id, 
FROM pcd_im_conversation
WHERE user_id = #{userId}
  AND target_id = #{targetId}
  AND conversation_type = #{conversationType}
  AND status = 0
